(83025,0,0,'Каждый выстрел - труп!',12,0,100,71,0,46240,85399,0,'Гром\'карский военачальник to 0'),
(83026,0,0,'Готовьте боевые машины к осаде!',12,0,100,396,0,46238,85397,0,'Осадный мастер Олугар to 0'),
