(96490,1,1,'Perfection! You can now make potions with precise exactitude!',12,0,0,0,0,0,98379,0,''),
(96499,4,0,'Повелитель Скверны уже близко!',12,0,100,0,0,55237,98272,0,'Джейс Темный Ткач to Player'),
(96512,0,0,'Defilers... I can smell the Nightmare in your blood. Be gone from these woods or suffer nature\'s wrath!',14,0,100,0,0,0,102280,0,'Arch-Druid Glaidalis to Player'),
