(96512,2,0,'Andu-falah-dor!',14,0,100,0,0,0,102289,0,'Arch-Druid Glaidalis to 0'),
(96512,2,1,'Be purified in the light of the stars!',14,0,100,0,0,0,102290,0,'Arch-Druid Glaidalis to 0'),
(96512,3,0,'I am the vessel of nature\'s fury!',14,0,100,0,0,0,102287,0,'Arch-Druid Glaidalis to 0'),
