(121694,3,0,'Вперед, братья и сестры орки! Покажите нам свой танец!',12,0,100,0,0,0,130779,0,'Аштар'),
(121694,4,0,'Покажите нам, как танцуют гоблины!',12,0,100,0,0,0,130774,0,'Аштар'),
