(121694,5,1,'Приглашаем на сцену Отрекшихся!',12,0,100,0,0,0,130767,0,'Аштар'),
(121694,6,0,'Эльфы крови! Теперь ваш черед.',12,0,100,0,0,0,130776,0,'Аштар'),
