(121739,0,1,'Давайте, пандарены!',12,0,100,0,0,0,131047,0,'Марла'),
(121739,1,0,'Это ваш город, люди. Покажите нам все свое величие!',12,0,100,0,0,0,131034,0,'Марла'),
